new file mode 100644
index 0000000..24d9f2d
--- /dev/null
+++ b/tests/transfer_test.go
@@ -0,0 +1,86 @@
+package tests
+
+import (
+	"errors"
+	"reflect"
+	"testing"
+
+	"example.com/bank/account"
+	"example.com/bank/ledger"
+)
+
+func newTransferLedger(t *testing.T) *ledger.Ledger {
+	t.Helper()
+	l := ledger.New()
+	a := account.New("a", "al", 100)
+	a.OverdraftLimit = 50
+	if err := l.Open(a); err != nil {
+		t.Fatal(err)
+	}
+	if err := l.Open(account.New("b", "bo", 10)); err != nil {
+		t.Fatal(err)
+	}
+	return l
+}
+
+func TestTransferSuccess(t *testing.T) {
+	l := newTransferLedger(t)
+	if err := l.Transfer("a", "b", 30, "rent"); err != nil {
+		t.Fatal(err)
+	}
+	a, _ := l.Get("a")
+	b, _ := l.Get("b")
+	if a.Balance != 70 || b.Balance != 40 {
+		t.Fatalf("balances = %d, %d; want 70, 40", a.Balance, b.Balance)
+	}
+	wantA := []account.Entry{{Kind: "transfer-out", Amount: -30, Memo: "rent", BalanceAfter: 70, Counterparty: "b"}}
+	wantB := []account.Entry{{Kind: "transfer-in", Amount: 30, Memo: "rent", BalanceAfter: 40, Counterparty: "a"}}
+	if !reflect.DeepEqual(a.History, wantA) {
+		t.Fatalf("a.History = %+v, want %+v", a.History, wantA)
+	}
+	if !reflect.DeepEqual(b.History, wantB) {
+		t.Fatalf("b.History = %+v, want %+v", b.History, wantB)
+	}
+}
+
+func TestTransferErrors(t *testing.T) {
+	cases := []struct {
+		name     string
+		from, to string
+		cents    int64
+		want     error
+	}{
+		{"zero amount", "a", "b", 0, ledger.ErrInvalidAmount},
+		{"negative amount", "a", "b", -5, ledger.ErrInvalidAmount},
+		{"same account", "a", "a", 10, ledger.ErrSameAccount},
+		{"same unknown account", "x", "x", 10, ledger.ErrSameAccount},
+		{"unknown source", "x", "b", 10, ledger.ErrUnknownAccount},
+		{"unknown destination", "a", "x", 10, ledger.ErrUnknownAccount},
+		{"overdraft exceeded", "a", "b", 151, ledger.ErrInsufficientFunds},
+	}
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			l := newTransferLedger(t)
+			err := l.Transfer(tc.from, tc.to, tc.cents, "")
+			if !errors.Is(err, tc.want) {
+				t.Fatalf("err = %v, want %v", err, tc.want)
+			}
+			a, _ := l.Get("a")
+			b, _ := l.Get("b")
+			if a.Balance != 100 || b.Balance != 10 || len(a.History) != 0 || len(b.History) != 0 {
+				t.Fatalf("state changed after failed transfer: a=%+v b=%+v", a, b)
+			}
+		})
+	}
+}
+
+func TestTransferToExactOverdraftLimit(t *testing.T) {
+	l := newTransferLedger(t)
+	if err := l.Transfer("a", "b", 150, ""); err != nil {
+		t.Fatalf("transfer to -50 with a 50 limit: %v", err)
+	}
+	a, _ := l.Get("a")
+	if a.Balance != -50 {
+		t.Fatalf("Balance = %d, want -50", a.Balance)
+	}
+}

diff --git a/tests/expr_spec.rs b/tests/expr_spec.rs
new file mode 100644
index 0000000..e96b821
--- /dev/null
+++ b/tests/expr_spec.rs
@@ -0,0 +1,106 @@
+use exprkit::{eval, EvalError};
+use std::collections::HashMap;
+
+fn run(s: &str) -> Result<f64, EvalError> {
+    eval(s, &HashMap::new())
+}
+
+fn with_x(s: &str, x: f64) -> Result<f64, EvalError> {
+    let mut vars = HashMap::new();
+    vars.insert("x".to_string(), x);
+    eval(s, &vars)
+}
+
+#[test]
+fn precedence_and_associativity() {
+    assert_eq!(run("-2^2"), Ok(-4.0));
+    assert_eq!(run("(-2)^2"), Ok(4.0));
+    assert_eq!(run("2^-1"), Ok(0.5));
+    assert_eq!(run("2^3^2"), Ok(512.0));
+    assert_eq!(run("--3"), Ok(3.0));
+    assert_eq!(run("2--2"), Ok(4.0));
+    assert_eq!(run("7 % 4 % 2"), Ok(1.0));
+    assert_eq!(run("-7 % 3"), Ok(-1.0));
+    assert_eq!(run("7.5 % 2"), Ok(1.5));
+}
+
+#[test]
+fn implicit_multiplication() {
+    assert_eq!(run("2(3+4)"), Ok(14.0));
+    assert_eq!(run("(1+2)(3+4)"), Ok(21.0));
+    assert_eq!(run("2(3)(4)"), Ok(24.0));
+    assert_eq!(run("3abs(-2)"), Ok(6.0));
+    assert_eq!(run("6/2(1+2)"), Ok(9.0));
+    assert_eq!(with_x("2x^2", 3.0), Ok(18.0));
+    assert_eq!(with_x("-2x", 3.0), Ok(-6.0));
+    assert_eq!(with_x("2^3x", 1.0), Ok(8.0));
+    assert_eq!(with_x("2 x", 5.0), Ok(10.0));
+}
+
+#[test]
+fn syntax_errors_and_positions() {
+    assert_eq!(run("2 3"), Err(EvalError::Parse { pos: 2 }));
+    assert_eq!(run("(2)3"), Err(EvalError::Parse { pos: 3 }));
+    assert_eq!(run("x 2"), Err(EvalError::Parse { pos: 2 }));
+    assert_eq!(run("1 + 2)"), Err(EvalError::Parse { pos: 5 }));
+    assert_eq!(run("()"), Err(EvalError::Parse { pos: 1 }));
+    assert_eq!(run("X"), Err(EvalError::Parse { pos: 0 }));
+    assert_eq!(run("1,2"), Err(EvalError::Parse { pos: 1 }));
+    assert_eq!(run("min(1 2)"), Err(EvalError::Parse { pos: 6 }));
+    assert_eq!(run("min(,1)"), Err(EvalError::Parse { pos: 4 }));
+    assert_eq!(run("min(1,)"), Err(EvalError::Parse { pos: 6 }));
+    assert_eq!(run(""), Err(EvalError::Parse { pos: 0 }));
+    assert_eq!(run("   "), Err(EvalError::Parse { pos: 3 }));
+    assert_eq!(run("(1 + 2"), Err(EvalError::Parse { pos: 6 }));
+    assert_eq!(run("1 +"), Err(EvalError::Parse { pos: 3 }));
+    assert_eq!(run("max(1"), Err(EvalError::Parse { pos: 5 }));
+    assert_eq!(run(".5"), Err(EvalError::Parse { pos: 0 }));
+    assert_eq!(run("5."), Err(EvalError::Parse { pos: 1 }));
+}
+
+#[test]
+fn functions_and_errors() {
+    assert_eq!(run("min()"), Err(EvalError::Arity {
+        name: "min".to_string(),
+        expected: "at least 1".to_string(),
+        got: 0,
+    }));
+    assert_eq!(run("abs(1, 2)"), Err(EvalError::Arity {
+        name: "abs".to_string(),
+        expected: "1".to_string(),
+        got: 2,
+    }));
+    assert_eq!(run("max(1, 7, 3)"), Ok(7.0));
+    assert_eq!(run("sqrt(-1)"), Err(EvalError::Domain("sqrt".to_string())));
+    assert_eq!(run("foo(1/0)"), Err(EvalError::UnknownFunc("foo".to_string())));
+    assert_eq!(run("1/0"), Err(EvalError::DivByZero));
+    assert_eq!(run("1/(0 * -1)"), Err(EvalError::DivByZero));
+    assert_eq!(with_x("x(1)", 2.0), Err(EvalError::UnknownFunc("x".to_string())));
+    assert_eq!(run("y"), Err(EvalError::UnknownVar("y".to_string())));
+    assert_eq!(run("1 + 2)  y"), Err(EvalError::Parse { pos: 5 }));
+}
+
+#[test]
+fn deep_and_long_inputs() {
+    let n = 100000;
+    let parens = format!("{}1{}", "(".repeat(n), ")".repeat(n));
+    assert_eq!(run(&parens), Ok(1.0));
+
+    let abs_calls = format!("{}-3{}", "abs(".repeat(n), ")".repeat(n));
+    assert_eq!(run(&abs_calls), Ok(3.0));
+
+    let max_calls = format!("{}5{}", "max(1, ".repeat(n), ")".repeat(n));
+    assert_eq!(run(&max_calls), Ok(5.0));
+
+    let signs = format!("{}3", "-".repeat(n));
+    assert_eq!(run(&signs), Ok(3.0));
+
+    let powers = format!("{}1", "1^".repeat(n));
+    assert_eq!(run(&powers), Ok(1.0));
+
+    let sum = vec!["1"; 200000].join("+");
+    assert_eq!(run(&sum), Ok(200000.0));
+
+    let repeated = "(1)".repeat(n);
+    assert_eq!(run(&repeated), Ok(1.0));
+}

diff --git a/tests/intervals_spec.rs b/tests/intervals_spec.rs
new file mode 100644
index 0000000..802c1b8
--- /dev/null
+++ b/tests/intervals_spec.rs
@@ -0,0 +1,89 @@
+use intervalkit::{Bound, IntervalSet};
+use Bound::{Closed as C, Open as O};
+
+#[test]
+fn empty_forms_are_ignored() {
+    let mut s = IntervalSet::new();
+    s.insert(O(2), O(2));
+    s.insert(C(2), O(2));
+    s.insert(O(2), C(2));
+    s.insert(C(3), C(2));
+    assert!(s.is_empty());
+    assert_eq!(s.to_string(), "{}");
+}
+
+#[test]
+fn merging_rules() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), O(3));
+    s.insert(C(3), C(5));
+    assert_eq!(s.ranges(), vec![(C(1), C(5))]);
+
+    let mut t = IntervalSet::new();
+    t.insert(C(1), O(3));
+    t.insert(O(3), C(5));
+    assert_eq!(t.ranges(), vec![(C(1), O(3)), (O(3), C(5))]);
+
+    let mut u = IntervalSet::new();
+    u.insert(O(1), O(3));
+    u.insert(C(3), C(3));
+    assert_eq!(u.ranges(), vec![(O(1), C(3))]);
+}
+
+#[test]
+fn remove_splits() {
+    let mut s = IntervalSet::new();
+    s.insert(C(1), C(5));
+    s.remove(C(2), C(2));
+    assert_eq!(s.to_string(), "{[1,2), (2,5]}");
+    let mut t = IntervalSet::new();
+    t.insert(C(1), C(5));
+    t.remove(O(2), O(4));
+    assert_eq!(t.to_string(), "{[1,2], [4,5]}");
+}
+
+#[test]
+fn complement_example() {
+    let mut s = IntervalSet::new();
+    s.insert(C(2), O(4));
+    s.insert(O(6), C(8));
+    assert_eq!(
+        s.complement(C(0), C(10)),
+        vec![(C(0), O(2)), (C(4), C(6)), (O(8), C(10))]
+    );
+    assert_eq!(s.measure(), 4);
+}
+
+#[test]
+fn extreme_endpoints_do_not_overflow() {
+    let mut s = IntervalSet::new();
+    s.insert(C(i64::MIN), C(i64::MAX));
+    assert!(s.contains(0.0));
+    assert_eq!(s.measure(), i64::MAX as i128 - i64::MIN as i128);
+    s.remove(C(i64::MIN), O(i64::MAX));
+    assert_eq!(s.to_string(), "{[9223372036854775807,9223372036854775807]}");
+}
+
+#[test]
+fn sweep_workload_is_fast() {
+    let start = std::time::Instant::now();
+    let mut s = IntervalSet::new();
+    let mut seed: u64 = 12345;
+    let mut next = || {
+        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
+        seed >> 33
+    };
+    for i in 0..300_000i64 {
+        let base = 1_000_000_000 - i * 3000;
+        let jitter = (next() % 2000) as i64;
+        let lo = base - jitter;
+        let len = (next() % 1001) as i64;
+        s.insert(C(lo), C(lo + len));
+        if i % 2 == 0 {
+            s.remove(C(lo + len / 2), C(lo + len / 2 + 1));
+        }
+        let x = (next() % 1_000_000_001) as f64;
+        let _ = s.contains(x);
+    }
+    assert!(start.elapsed().as_secs_f64() < 3.0);
+}

