@@ -0,0 +1,98 @@
+use romankit::roman::{from_roman, to_roman, RomanError};
+
+fn canon(n: u32) -> String {
+    match to_roman(n) {
+        Ok(s) => s,
+        Err(_) => panic!("to_roman({}) should be Ok", n),
+    }
+}
+
+fn ok(s: &str) -> u32 {
+    match from_roman(s) {
+        Ok(n) => n,
+        Err(_) => panic!("from_roman({:?}) should be Ok", s),
+    }
+}
+
+#[test]
+fn subtractive_pairs_at_end_parse_correctly() {
+    assert_eq!(ok("IV"), 4);
+    assert_eq!(ok("XIV"), 14);
+    assert_eq!(ok("XIX"), 19);
+    assert!(!matches!(from_roman("IV"), Err(RomanError::OutOfRange)));
+}
+
+#[test]
+fn lenient_junk_is_rejected_as_noncanonical() {
+    for s in ["IIII", "IC", "VX", "MMMM", "IIV", "XM"] {
+        assert!(
+            matches!(from_roman(s), Err(RomanError::NonCanonical)),
+            "{} should be NonCanonical",
+            s
+        );
+    }
+}
+
+#[test]
+fn empty_string_is_empty_error() {
+    assert!(matches!(from_roman(""), Err(RomanError::Empty)));
+}
+
+#[test]
+fn lowercase_is_invalid_char_not_parsed() {
+    assert!(matches!(from_roman("xiv"), Err(RomanError::InvalidChar('x'))));
+    assert!(!matches!(from_roman("xiv"), Ok(_)));
+}
+
+#[test]
+fn first_invalid_char_is_reported() {
+    assert!(matches!(from_roman("XiV"), Err(RomanError::InvalidChar('i'))));
+    assert!(matches!(from_roman("IV "), Err(RomanError::InvalidChar(' '))));
+    assert!(matches!(from_roman("IVAB"), Err(RomanError::InvalidChar('A'))));
+}
+
+#[test]
+fn invalid_char_takes_precedence_over_noncanonical() {
+    assert!(matches!(from_roman("IIIIx"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("MMMMx"), Err(RomanError::InvalidChar('x'))));
+}
+
+#[test]
+fn to_roman_rejects_out_of_range() {
+    assert!(matches!(to_roman(0), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(4000), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(u32::MAX), Err(RomanError::OutOfRange)));
+}
+
+#[test]
+fn to_roman_renders_range_bounds_canonically() {
+    assert_eq!(canon(1), "I");
+    assert_eq!(canon(4), "IV");
+    assert_eq!(canon(1994), "MCMXCIV");
+    assert_eq!(canon(3999), "MMMCMXCIX");
+    assert!(!matches!(to_roman(3999), Err(RomanError::OutOfRange)));
+}
+
+#[test]
+fn round_trip_holds_for_every_valid_number() {
+    for n in 1..=3999u32 {
+        let s = canon(n);
+        assert_eq!(ok(&s), n, "round trip failed for {}", n);
+    }
+}
+
+#[test]
+fn from_roman_accepts_only_canonical_forms() {
+    for n in 1..=3999u32 {
+        let s = canon(n);
+        let t = &s[..s.len() - 1];
+        if t.is_empty() {
+            continue;
+        }
+        match from_roman(t) {
+            Ok(m) => assert_eq!(canon(m).as_str(), t, "{} accepted but not canonical", t),
+            Err(RomanError::OutOfRange) => panic!("from_roman({:?}) returned OutOfRange", t),
+            Err(_) => {}
+        }
+    }
+}
