+use statkit::stats::{count, mean, median, percentile};
+use statkit::summary;
+
+const NAN: f64 = f64::NAN;
+
+fn assert_opt_close(actual: Option<f64>, expected: f64) {
+    match actual {
+        Some(v) => assert!((v - expected).abs() < 1e-9, "expected {expected}, got {v}"),
+        None => panic!("expected Some({expected}), got None"),
+    }
+}
+
+#[test]
+fn count_ignores_nan_values() {
+    assert_eq!(count(&[1.0, NAN, 3.0]), 2);
+    assert_eq!(count(&[NAN, NAN]), 0);
+    assert_eq!(count(&[]), 0);
+    assert_ne!(count(&[1.0, NAN, 3.0]), 3);
+}
+
+#[test]
+fn mean_ignores_nan_and_is_none_when_undefined() {
+    assert_opt_close(mean(&[1.0, 2.0, 3.0, 4.0]), 2.5);
+    assert_opt_close(mean(&[1.0, NAN, 3.0]), 2.0);
+    assert_eq!(mean(&[]), None);
+    assert_eq!(mean(&[NAN]), None);
+    assert_opt_close(mean(&[1.0, NAN]), 1.0);
+}
+
+#[test]
+fn median_is_percentile_50_and_ignores_nan() {
+    assert_opt_close(median(&[1.0, 2.0, 3.0, 4.0]), 2.5);
+    assert_opt_close(median(&[3.0, 1.0, 2.0]), 2.0);
+    assert_opt_close(median(&[3.0, NAN, 1.0, 2.0]), 2.0);
+    assert_eq!(median(&[]), None);
+    assert_eq!(median(&[NAN]), None);
+    assert_ne!(median(&[3.0, 1.0, 2.0]), Some(3.0));
+}
+
+#[test]
+fn percentile_uses_linear_interpolation_between_closest_ranks() {
+    assert_opt_close(percentile(&[1.0, 2.0, 3.0, 4.0], 90.0), 3.7);
+    assert_opt_close(percentile(&[1.0, 2.0, 3.0, 4.0], 0.0), 1.0);
+    assert_opt_close(percentile(&[1.0, 2.0, 3.0, 4.0], 100.0), 4.0);
+    assert_opt_close(percentile(&[10.0, 20.0, 30.0], 25.0), 15.0);
+    assert_ne!(percentile(&[1.0, 2.0, 3.0, 4.0], 90.0), Some(3.0));
+}
+
+#[test]
+fn percentile_does_not_depend_on_input_order_and_does_not_mutate_input() {
+    let ordered = [1.0, 2.0, 3.0, 4.0];
+    let shuffled = [4.0, 1.0, 3.0, 2.0];
+    assert_opt_close(percentile(&shuffled, 90.0), 3.7);
+    assert_eq!(percentile(&shuffled, 50.0), percentile(&ordered, 50.0));
+    assert_eq!(shuffled, [4.0, 1.0, 3.0, 2.0]);
+}
+
+#[test]
+fn percentile_ignores_nan_and_is_none_when_undefined() {
+    assert_opt_close(percentile(&[NAN, 4.0, 1.0, 3.0, 2.0], 100.0), 4.0);
+    assert_opt_close(percentile(&[NAN, 4.0, 1.0, 3.0, 2.0], 0.0), 1.0);
+    assert_eq!(percentile(&[], 50.0), None);
+    assert_eq!(percentile(&[NAN], 50.0), None);
+    assert_opt_close(percentile(&[NAN, 4.0], 0.0), 4.0);
+}
+
+#[test]
+fn percentile_rejects_invalid_p() {
+    assert_eq!(percentile(&[1.0, 2.0, 3.0], NAN), None);
+    assert_eq!(percentile(&[1.0, 2.0, 3.0], -0.5), None);
+    assert_eq!(percentile(&[1.0, 2.0, 3.0], 100.5), None);
+    assert!(percentile(&[1.0, 2.0, 3.0], 100.0).is_some());
+}
+
+#[test]
+fn summary_prints_fixed_two_decimal_report() {
+    assert_eq!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_eq!(summary(&[4.0, 1.0, 3.0, 2.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_ignores_nan_and_reports_only_count_when_undefined() {
+    assert_eq!(summary(&[1.0, NAN, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_eq!(summary(&[]), "n=0");
+    assert_eq!(summary(&[NAN, NAN]), "n=0");
+    assert_ne!(summary(&[]), "n=0 mean=NaN p50=0.00 p90=0.00");
+}

