+use stockkit::{Inventory, Order, ReserveError};
+
+#[test]
+fn quantities_by_sku_sums_sorts_and_drops_zero() {
+    let order = Order::new("o-2")
+        .with_line("pear", 2)
+        .with_line("apple", 1)
+        .with_line("pear", 3)
+        .with_line("plum", 0);
+    assert_eq!(
+        order.quantities_by_sku(),
+        vec![("apple".to_string(), 1), ("pear".to_string(), 5)]
+    );
+}
+
+#[test]
+fn reserve_reduces_available_but_not_on_hand() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let order = Order::new("o-3").with_line("apple", 4);
+    let id = inv.reserve(&order).unwrap();
+    assert_eq!(inv.available("apple"), 6);
+    assert_eq!(inv.on_hand("apple"), 10);
+    inv.release(id).unwrap();
+    assert_eq!(inv.available("apple"), 10);
+    assert_eq!(inv.on_hand("apple"), 10);
+}
+
+#[test]
+fn reserve_is_all_or_nothing_and_reports_first_failure_in_sku_order() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 1);
+    inv.add_stock("pear", 1);
+    let order = Order::new("o-4")
+        .with_line("pear", 5)
+        .with_line("apple", 2)
+        .with_line("kiwi", 1);
+    // Sorted order is apple, kiwi, pear: apple fails first.
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::Insufficient {
+            sku: "apple".to_string(),
+            requested: 2,
+            available: 1,
+        })
+    );
+    assert_eq!(inv.available("apple"), 1);
+    assert_eq!(inv.available("pear"), 1);
+}
+
+#[test]
+fn unknown_sku_fails_and_is_reported() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 3);
+    let order = Order::new("o-5").with_line("apple", 1).with_line("kiwi", 1);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::UnknownSku("kiwi".to_string()))
+    );
+    assert_eq!(inv.available("apple"), 3);
+}
+
+#[test]
+fn commit_drops_on_hand_and_keeps_available() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let id = inv
+        .reserve(&Order::new("o-6").with_line("apple", 4))
+        .unwrap();
+    let before = inv.available("apple");
+    inv.commit(id).unwrap();
+    assert_eq!(inv.on_hand("apple"), 6);
+    assert_eq!(inv.available("apple"), before);
+    assert_eq!(inv.commit(id), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn ids_are_not_reused_and_empty_order_holds_nothing() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 2);
+    let a = inv.reserve(&Order::new("o-7")).unwrap();
+    let b = inv.reserve(&Order::new("o-8").with_line("apple", 0)).unwrap();
+    assert_ne!(a, b);
+    assert_eq!(inv.available("apple"), 2);
+    inv.release(a).unwrap();
+    let c = inv.reserve(&Order::new("o-9").with_line("apple", 1)).unwrap();
+    assert_ne!(c, a);
+    assert_ne!(c, b);
+}
+
+#[test]
+fn unknown_reservation_is_rejected() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 2);
+    let id = inv.reserve(&Order::new("o-10").with_line("apple", 1)).unwrap();
+    inv.release(id).unwrap();
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+    assert_eq!(
+        inv.commit(stockkit::ReservationId(999)),
+        Err(ReserveError::UnknownReservation)
+    );
+}

