+++ b/test/cron.test.ts
@@ -0,0 +1,48 @@
+import { expect, test } from "bun:test";
+import { CronError, nextRun } from "../src/cron";
+
+const iso = (s: string) => new Date(s);
+
+test("steps and lists", () => {
+  expect(nextRun("*/15 * * * *", iso("2026-01-01T00:07:30Z")).toISOString()).toBe("2026-01-01T00:15:00.000Z");
+  expect(nextRun("10-50/20 * * * *", iso("2026-01-01T00:10:00Z")).toISOString()).toBe("2026-01-01T00:30:00.000Z");
+});
+
+test("aliases are case-insensitive and exact", () => {
+  expect(nextRun("@YEARLY", iso("2026-03-05T00:00:00Z")).toISOString()).toBe("2027-01-01T00:00:00.000Z");
+  expect(() => nextRun("@daily now", iso("2026-01-01T00:00:00Z"))).toThrow(CronError);
+  expect(() => nextRun("@sometimes", iso("2026-01-01T00:00:00Z"))).toThrow(CronError);
+});
+
+test("names and day-of-week 7 as Sunday", () => {
+  expect(nextRun("0 0 * jan,Jul MON-FRI", iso("2026-01-03T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  expect(nextRun("0 0 * * 7", iso("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T00:00:00.000Z");
+});
+
+test("OR rule when both day fields restricted", () => {
+  // Last day of Jan 2026 is a Saturday; the next Monday (Jan 5) comes first.
+  expect(nextRun("0 0 L * 1", iso("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  // Last Friday of Feb 2026 is the 27th.
+  expect(nextRun("0 0 * 2 5L", iso("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-02-27T00:00:00.000Z");
+});
+
+test("nth weekday and nearest weekday", () => {
+  expect(nextRun("0 0 * * 5#3", iso("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-16T00:00:00.000Z");
+  // 15 Feb 2026 is a Sunday, so the nearest weekday is Monday the 16th.
+  expect(nextRun("0 12 15W 2 *", iso("2026-02-01T00:00:00Z")).toISOString()).toBe("2026-02-16T12:00:00.000Z");
+  // 31W never matches in February, so there is no run within 5 years.
+  expect(() => nextRun("0 0 31W 2 *", iso("2026-01-01T00:00:00Z"))).toThrow(CronError);
+});
+
+test("invalid expressions throw CronError", () => {
+  const bad = ["5/15 * * * *", "5-1 * * * *", "60 * * * *", "* * * * 8#1", "* * * * 1#0", "* * 1-5W * *", "* * * * 1,,2", "* * * JANX *", "* * * * *W", "* * * *"];
+  for (const e of bad) expect(() => nextRun(e, iso("2026-01-01T00:00:00Z"))).toThrow(CronError);
+  expect(() => nextRun("0 0 30 2 *", iso("2026-01-01T00:00:00Z"))).toThrow(CronError);
+});
+
+test("does not modify from", () => {
+  const from = iso("2026-01-01T00:00:30.500Z");
+  const out = nextRun("* * * * *", from);
+  expect(out.toISOString()).toBe("2026-01-01T00:01:00.000Z");
+  expect(from.toISOString()).toBe("2026-01-01T00:00:30.500Z");
+});

