+package tests
+
+import (
+	"reflect"
+	"testing"
+	"time"
+
+	"example.com/appcfg/config"
+	"example.com/appcfg/server"
+)
+
+func TestFileDurationTimeout(t *testing.T) {
+	s, err := server.Load("timeout = 1m30s\n", nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.Timeout != 90*time.Second {
+		t.Fatalf("Timeout = %v, want 90s", s.Timeout)
+	}
+}
+
+func TestEmptyEnvDoesNotOverrideFile(t *testing.T) {
+	s, err := server.Load("port = 9000\n", map[string]string{"APP_PORT": ""})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.Port != 9000 {
+		t.Fatalf("Port = %d, want 9000", s.Port)
+	}
+}
+
+func TestFileValueWithEquals(t *testing.T) {
+	s, err := server.Load("dsn = user=app password=s3cret\n", nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.DSN != "user=app password=s3cret" {
+		t.Fatalf("DSN = %q, want %q", s.DSN, "user=app password=s3cret")
+	}
+}
+
+func TestParseFileSplitsOnFirstEquals(t *testing.T) {
+	got, err := config.ParseFile("a = b=c")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if want := map[string]string{"a": "b=c"}; !reflect.DeepEqual(got, want) {
+		t.Fatalf("ParseFile = %v, want %v", got, want)
+	}
+}
+
+func TestFromEnvIgnoresEmptyValues(t *testing.T) {
+	got := config.FromEnv(map[string]string{"APP_PORT": "", "APP_LOG_LEVEL": "debug"})
+	if want := map[string]string{"log_level": "debug"}; !reflect.DeepEqual(got, want) {
+		t.Fatalf("FromEnv = %v, want %v", got, want)
+	}
+}
+
+func TestDurationForms(t *testing.T) {
+	cases := map[string]time.Duration{
+		"45":    45 * time.Second,
+		"1m30s": 90 * time.Second,
+		"250ms": 250 * time.Millisecond,
+		"1.5s":  1500 * time.Millisecond,
+		"2h":    2 * time.Hour,
+		"bogus": 30 * time.Second,
+		"":      30 * time.Second,
+	}
+	for in, want := range cases {
+		cfg, err := config.Load("timeout = "+in+"\n", nil)
+		if err != nil {
+			t.Fatal(err)
+		}
+		if got := cfg.Duration("timeout", 30*time.Second); got != want {
+			t.Errorf("Duration(%q) = %v, want %v", in, got, want)
+		}
+	}
+}

