+package sched
+
+import (
+	"errors"
+	"fmt"
+	"reflect"
+	"testing"
+	"time"
+)
+
+func TestPlanBatches(t *testing.T) {
+	got, err := Plan(map[string][]string{
+		"app":  {"lib", "util", "lib"},
+		"lib":  {"util"},
+		"util": nil,
+		"doc":  {},
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	want := [][]string{{"doc", "util"}, {"lib"}, {"app"}}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("Plan = %v, want %v", got, want)
+	}
+}
+
+func TestPlanEmpty(t *testing.T) {
+	got, err := Plan(nil)
+	if err != nil || got == nil || len(got) != 0 {
+		t.Fatalf("Plan(nil) = %v, %v", got, err)
+	}
+}
+
+func TestPlanUnknownBeforeCycle(t *testing.T) {
+	_, err := Plan(map[string][]string{
+		"a": {"b", "zz", "yy"},
+		"b": {"a"},
+		"c": {"nope"},
+	})
+	var ue *UnknownDepError
+	if !errors.As(err, &ue) || ue.Task != "a" || ue.Dep != "yy" {
+		t.Fatalf("err = %v", err)
+	}
+	if ue.Error() != fmt.Sprintf("task %q depends on unknown task %q", "a", "yy") {
+		t.Fatalf("Error() = %q", ue.Error())
+	}
+}
+
+func TestPlanCyclePaths(t *testing.T) {
+	cases := []struct {
+		tasks map[string][]string
+		want  string
+	}{
+		{map[string][]string{"a": {"b"}, "b": {"a"}}, "dependency cycle: a -> b -> a"},
+		{map[string][]string{"b": {"b"}}, "dependency cycle: b -> b"},
+		{map[string][]string{
+			"p": {"r", "q"},
+			"q": {"s"},
+			"s": {"p"},
+			"r": {"p"},
+		}, "dependency cycle: p -> q -> s -> p"},
+		{map[string][]string{
+			"z": {"a"},
+			"a": {"b"},
+			"b": {"a"},
+		}, "dependency cycle: a -> b -> a"},
+	}
+	for _, c := range cases {
+		_, err := Plan(c.tasks)
+		var ce *CycleError
+		if !errors.As(err, &ce) || ce.Error() != c.want {
+			t.Fatalf("err = %v, want %q", err, c.want)
+		}
+	}
+}
+
+func TestSimulateBasic(t *testing.T) {
+	s, err := Simulate(map[string]Task{
+		"a": {Duration: 3},
+		"b": {Deps: []string{"a"}, Duration: 2},
+		"c": {Duration: 5, Priority: 1},
+	}, 1)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.Slots["c"] != (Slot{0, 5, 0}) || s.Slots["a"] != (Slot{5, 8, 0}) || s.Slots["b"] != (Slot{8, 10, 0}) {
+		t.Fatalf("slots = %v", s.Slots)
+	}
+	if s.Makespan != 10 || !reflect.DeepEqual(s.CriticalPath, []string{"a", "b"}) {
+		t.Fatalf("makespan %d path %v", s.Makespan, s.CriticalPath)
+	}
+}
+
+func TestSimulateErrors(t *testing.T) {
+	if _, err := Simulate(map[string]Task{"a": {Duration: 1}}, 0); !errors.Is(err, ErrNoWorkers) {
+		t.Fatalf("err = %v", err)
+	}
+	_, err := Simulate(map[string]Task{"b": {Duration: 0}, "a": {Duration: -1}}, 2)
+	var ide *InvalidDurationError
+	if !errors.As(err, &ide) || ide.Task != "a" {
+		t.Fatalf("err = %v", err)
+	}
+}
+
+func TestSimulateEmpty(t *testing.T) {
+	s, err := Simulate(nil, 4)
+	if err != nil || s.Slots == nil || s.CriticalPath == nil || s.Makespan != 0 {
+		t.Fatalf("Simulate(nil) = %+v, %v", s, err)
+	}
+}
+
+func TestPlanScaleChainAndRing(t *testing.T) {
+	const n = 200000
+	chain := make(map[string][]string, n)
+	name := func(i int) string { return fmt.Sprintf("t%07d", i) }
+	for i := 0; i < n; i++ {
+		if i > 0 {
+			chain[name(i)] = []string{name(i - 1), name(i - 1)}
+		} else {
+			chain[name(i)] = nil
+		}
+	}
+	start := time.Now()
+	if _, err := Plan(chain); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := Simulate(func() map[string]Task {
+		m := make(map[string]Task, n)
+		for k, v := range chain {
+			m[k] = Task{Deps: v, Duration: 1}
+		}
+		return m
+	}(), 8); err != nil {
+		t.Fatal(err)
+	}
+	ring := make(map[string][]string, n)
+	const r = 100000
+	for i := 0; i < r; i++ {
+		ring[name(i)] = []string{name((i + 1) % r)}
+	}
+	for i := r; i < n; i++ {
+		ring[name(i)] = []string{name(i - 1)}
+	}
+	_, err := Plan(ring)
+	var ce *CycleError
+	if !errors.As(err, &ce) || len(ce.Path) != r+1 {
+		t.Fatalf("ring err = %v", err)
+	}
+	if el := time.Since(start); el > 20*time.Second {
+		t.Fatalf("too slow: %v", el)
+	}
+}

