+
+#[test]
+fn large_workload_runs_under_three_seconds() {
+    let mut state: u64 = 0x9E3779B97F4A7C15;
+    let mut next = move || {
+        state = state
+            .wrapping_mul(6364136223846793005)
+            .wrapping_add(1442695040888963407);
+        state >> 33
+    };
+
+    let mut s = IntervalSet::new();
+    let start = Instant::now();
+    for i in 0..300_000i64 {
+        let jitter = (next() % 2000) as i64;
+        let pos = 1_000_000_000i64 - i * 3000 - jitter;
+        let len = (next() % 1001) as i64;
+        s.insert(Bound::Closed(pos), Bound::Closed(pos + len));
+        if i % 3 == 0 {
+            let rp = 1_000_000_000i64 - i * 3000 - 6000;
+            s.remove(Bound::Closed(rp), Bound::Closed(rp));
+        }
+        let x = (next() % 1_000_000_001) as f64;
+        let _ = s.contains(x);
+    }
+    let elapsed = start.elapsed();
+    assert!(!s.is_empty());
+    assert!(
+        elapsed.as_secs_f64() < 3.0,
+        "workload took {:?}",
+        elapsed
+    );
+}

