+use romankit::{from_roman, to_roman, RomanError};
+use std::collections::HashMap;
+
+#[test]
+fn subtractive_endings_parse_correctly() {
+    assert_eq!(from_roman("IV").ok(), Some(4));
+    assert_eq!(from_roman("XIX").ok(), Some(19));
+    assert!(!matches!(from_roman("IIII"), Ok(_)));
+}
+
+#[test]
+fn junk_numerals_are_non_canonical() {
+    for s in ["IIII", "IC", "VX", "MMMM", "IIV", "XM"] {
+        assert!(matches!(from_roman(s), Err(RomanError::NonCanonical)), "{s}");
+    }
+    assert!(from_roman("IV").is_ok());
+}
+
+#[test]
+fn empty_string_is_empty_error() {
+    assert!(matches!(from_roman(""), Err(RomanError::Empty)));
+    assert!(from_roman("I").is_ok());
+}
+
+#[test]
+fn lowercase_is_invalid_char() {
+    assert!(matches!(from_roman("xiv"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("I V"), Err(RomanError::InvalidChar(' '))));
+    assert!(from_roman("XIV").is_ok());
+}
+
+#[test]
+fn invalid_char_reported_before_non_canonical() {
+    assert!(matches!(from_roman("IIIIx"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("xIIII"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("IVab"), Err(RomanError::InvalidChar('a'))));
+}
+
+#[test]
+fn to_roman_rejects_out_of_range() {
+    assert!(matches!(to_roman(0), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(4000), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(u32::MAX), Err(RomanError::OutOfRange)));
+    assert_eq!(to_roman(1).ok().as_deref(), Some("I"));
+}
+
+#[test]
+fn to_roman_produces_canonical_numerals() {
+    assert_eq!(to_roman(4).ok().as_deref(), Some("IV"));
+    assert_eq!(to_roman(19).ok().as_deref(), Some("XIX"));
+    assert_eq!(to_roman(3999).ok().as_deref(), Some("MMMCMXCIX"));
+}
+
+#[test]
+fn from_roman_never_reports_out_of_range() {
+    for n in 1..=3999u32 {
+        let s = to_roman(n).ok().unwrap();
+        assert!(!matches!(from_roman(&s), Err(RomanError::OutOfRange)));
+        assert_eq!(from_roman(&s).ok(), Some(n));
+    }
+    assert!(!matches!(from_roman("MMMM"), Err(RomanError::OutOfRange)));
+}
+
+#[test]
+fn accepts_exactly_canonical_forms() {
+    let mut canon: HashMap<String, u32> = HashMap::new();
+    for n in 1..=3999u32 {
+        canon.insert(to_roman(n).ok().unwrap(), n);
+    }
+    let letters = ['I', 'V', 'X', 'L', 'C', 'D', 'M'];
+    let mut candidates: Vec<String> = vec![String::new()];
+    let mut frontier: Vec<String> = vec![String::new()];
+    for _ in 0..6 {
+        let mut next = Vec::new();
+        for prefix in &frontier {
+            for &c in &letters {
+                let mut s = prefix.clone();
+                s.push(c);
+                next.push(s);
+            }
+        }
+        candidates.extend(next.iter().cloned());
+        frontier = next;
+    }
+    for s in candidates.iter().filter(|s| !s.is_empty()) {
+        match from_roman(s) {
+            Ok(v) => assert_eq!(canon.get(s.as_str()).copied(), Some(v), "{s}"),
+            Err(RomanError::NonCanonical) => assert!(!canon.contains_key(s.as_str()), "{s}"),
+            Err(_) => panic!("unexpected error for {s}"),
+        }
+    }
+}
