+use shapekit::{Shape, ShapeError};
+use std::f64::consts::PI;
+
+const EPS: f64 = 1e-9;
+
+fn close(got: f64, want: f64) -> bool {
+    (got - want).abs() < EPS
+}
+
+fn assert_copy<T: Copy>() {}
+fn assert_eq_bound<T: Eq>() {}
+
+#[test]
+fn shape_and_error_derive_required_traits() {
+    assert_copy::<Shape>();
+    assert_eq_bound::<ShapeError>();
+    let s = Shape::Circle { r: 1.0 };
+    let t = s;
+    assert_eq!(s, t);
+    assert_ne!(s, Shape::Circle { r: 2.0 });
+}
+
+#[test]
+fn parse_accepts_kinds_case_insensitively() {
+    assert_eq!(Shape::parse("CIRCLE", &[1.0]), Ok(Shape::Circle { r: 1.0 }));
+    assert_eq!(Shape::parse("Rectangle", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(Shape::parse("rect", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(
+        Shape::parse("Triangle", &[3.0, 4.0, 5.0]),
+        Ok(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 })
+    );
+    assert_eq!(Shape::parse("SQUARE", &[2.0]), Ok(Shape::Rect { w: 2.0, h: 2.0 }));
+    assert_eq!(Shape::parse("square", &[]), Err(ShapeError::WrongParamCount { expected: 1, got: 0 }));
+}
+
+#[test]
+fn parse_rejects_unknown_kind_keeping_caller_spelling() {
+    assert_eq!(
+        Shape::parse("Hexagon", &[1.0]),
+        Err(ShapeError::UnknownKind("Hexagon".to_string()))
+    );
+    assert_ne!(Shape::parse("circle", &[1.0]), Err(ShapeError::UnknownKind("circle".to_string())));
+}
+
+#[test]
+fn parse_checks_kind_then_count_then_negative_then_triangle() {
+    assert_eq!(Shape::parse("hexagon", &[]), Err(ShapeError::UnknownKind("hexagon".to_string())));
+    assert_eq!(
+        Shape::parse("circle", &[-1.0, 2.0]),
+        Err(ShapeError::WrongParamCount { expected: 1, got: 2 })
+    );
+    assert_eq!(Shape::parse("circle", &[-1.0]), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::parse("triangle", &[-1.0, 1.0, 1.0]), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::parse("triangle", &[1.0, 1.0, 3.0]), Err(ShapeError::InvalidTriangle));
+}
+
+#[test]
+fn zero_dimensions_are_valid_and_degenerate_triangle_has_zero_area() {
+    assert_eq!(Shape::parse("circle", &[0.0]), Ok(Shape::Circle { r: 0.0 }));
+    assert!(close(Shape::Circle { r: 0.0 }.area().unwrap(), 0.0));
+    let t = Shape::parse("triangle", &[1.0, 2.0, 3.0]).unwrap();
+    assert!(close(t.area().unwrap(), 0.0));
+    assert!(close(t.perimeter().unwrap(), 6.0));
+    assert_eq!(Shape::Triangle { a: 1.0, b: 1.0, c: 3.0 }.area(), Err(ShapeError::InvalidTriangle));
+}
+
+#[test]
+fn area_and_perimeter_values_match_formulas() {
+    let c = Shape::Circle { r: 2.0 };
+    assert!(close(c.area().unwrap(), 4.0 * PI));
+    assert!(close(c.perimeter().unwrap(), 4.0 * PI));
+    let r = Shape::Rect { w: 2.0, h: 3.0 };
+    assert!(close(r.area().unwrap(), 6.0));
+    assert!(close(r.perimeter().unwrap(), 10.0));
+    let t = Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 };
+    assert!(close(t.area().unwrap(), 6.0));
+    assert!(close(t.perimeter().unwrap(), 12.0));
+    let s = Shape::parse("square", &[2.0]).unwrap();
+    assert!(close(s.area().unwrap(), 4.0));
+    assert!(close(s.perimeter().unwrap(), 8.0));
+}
+
+#[test]
+fn directly_built_shapes_are_validated_negative_before_triangle() {
+    assert_eq!(Shape::Circle { r: -1.0 }.area(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Circle { r: -1.0 }.perimeter(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Rect { w: -1.0, h: 2.0 }.perimeter(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Rect { w: 1.0, h: -2.0 }.area(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Triangle { a: -1.0, b: 1.0, c: 1.0 }.area(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Triangle { a: -1.0, b: 1.0, c: 1.0 }.perimeter(), Err(ShapeError::NegativeDimension));
+    assert_eq!(Shape::Triangle { a: 1.0, b: 1.0, c: 3.0 }.perimeter(), Err(ShapeError::InvalidTriangle));
+}
+
+#[test]
+fn error_display_messages_are_exact() {
+    assert_eq!(
+        ShapeError::UnknownKind("Hexagon".to_string()).to_string(),
+        "unknown shape kind: Hexagon"
+    );
+    assert_eq!(
+        ShapeError::WrongParamCount { expected: 2, got: 1 }.to_string(),
+        "expected 2 params, got 1"
+    );
+    assert_eq!(ShapeError::NegativeDimension.to_string(), "dimensions must be non-negative");
+    assert_eq!(ShapeError::InvalidTriangle.to_string(), "sides do not form a triangle");
+}
+
+#[test]
+fn free_area_and_perimeter_keep_signatures_and_messages() {
+    assert!(close(shapekit::area("rect", &[2.0, 3.0]).unwrap(), 6.0));
+    assert!(close(shapekit::area::area("rect", &[2.0, 3.0]).unwrap(), 6.0));
+    assert!(close(shapekit::perimeter("RECTANGLE", &[2.0, 3.0]).unwrap(), 10.0));
+    assert!(close(shapekit::area("Square", &[2.0]).unwrap(), 4.0));
+    assert_eq!(
+        shapekit::area("circle", &[-1.0]),
+        Err("dimensions must be non-negative".to_string())
+    );
+    assert_eq!(shapekit::area("Hexagon", &[]), Err("unknown shape kind: Hexagon".to_string()));
+    assert_eq!(shapekit::area("rect", &[1.0]), Err("expected 2 params, got 1".to_string()));
+    assert_eq!(
+        shapekit::perimeter("triangle", &[1.0, 1.0, 3.0]),
+        Err("sides do not form a triangle".to_string())
+    );
+    assert_eq!(
+        shapekit::perimeter::perimeter("circle", &[-1.0, 2.0]),
+        Err("expected 1 params, got 2".to_string())
+    );
+}

