+use stockkit::{Inventory, Order, ReserveError};
+
+#[test]
+fn quantities_by_sku_sums_sorts_and_drops_zero() {
+    let order = Order::new("o")
+        .with_line("pear", 2)
+        .with_line("apple", 1)
+        .with_line("pear", 3)
+        .with_line("fig", 0);
+    assert_eq!(
+        order.quantities_by_sku(),
+        vec![("apple".to_string(), 1), ("pear".to_string(), 5)]
+    );
+}
+
+#[test]
+fn reserve_reduces_available_but_not_on_hand() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 4)).unwrap();
+    assert_eq!(inv.available("apple"), 6);
+    assert_eq!(inv.on_hand("apple"), 10);
+    inv.release(id).unwrap();
+    assert_eq!(inv.available("apple"), 10);
+}
+
+#[test]
+fn commit_drops_on_hand_and_keeps_available() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 4)).unwrap();
+    inv.commit(id).unwrap();
+    assert_eq!(inv.on_hand("apple"), 6);
+    assert_eq!(inv.available("apple"), 6);
+    assert_eq!(inv.commit(id), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn reserve_is_all_or_nothing_and_reports_first_failure() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 1);
+    let order = Order::new("o")
+        .with_line("apple", 1)
+        .with_line("kiwi", 1)
+        .with_line("pear", 5);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::UnknownSku("kiwi".to_string()))
+    );
+    assert_eq!(inv.available("apple"), 1);
+
+    inv.add_stock("kiwi", 1);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::UnknownSku("pear".to_string()))
+    );
+    inv.add_stock("pear", 2);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::Insufficient {
+            sku: "pear".to_string(),
+            requested: 5,
+            available: 2,
+        })
+    );
+    assert_eq!(inv.available("apple"), 1);
+}
+
+#[test]
+fn ids_are_never_reused() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 3);
+    let a = inv.reserve(&Order::new("o").with_line("apple", 1)).unwrap();
+    inv.release(a).unwrap();
+    let b = inv.reserve(&Order::new("o").with_line("apple", 1)).unwrap();
+    assert_ne!(a, b);
+    assert_eq!(inv.release(a), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn empty_order_gets_fresh_id_holding_nothing() {
+    let mut inv = Inventory::new();
+    let id = inv.reserve(&Order::new("o").with_line("x", 0)).unwrap();
+    inv.commit(id).unwrap();
+    assert_eq!(inv.available("x"), 0);
+}

