+test("undefined and empty code behave like no code", () => {
+  expect(cartTotal(small, undefined)).toBe(2899);
+  expect(cartTotal(small, "")).toBe(2899);
+});
+
+test("SAVE10 takes 10% off the subtotal, rounded to the cent", () => {
+  expect(cartTotal(small, "SAVE10")).toBe(2400 - 240 + 499);
+  expect(cartTotal([{ sku: "x", priceCents: 1505, qty: 1 }], "SAVE10")).toBe(
+    1505 - 151 + 499,
