+
+test("3000 calls over rare schedules finish under 2 seconds", () => {
+  const schedules = ["0 0 29 2 1", "59 23 31 12 5L", "0 0 LW 2 *", "30 4 15W * 1#5", "0 0 29 2 *"];
+  const start = Date.now();
+  for (let i = 0; i < 3000; i++) {
+    const year = 2000 + (i % 100);
+    const from = new Date(Date.UTC(year, i % 12, 1 + (i % 28)));
+    try {
+      nextRun(schedules[i % schedules.length], from);
+    } catch (e) {
+      expect(e).toBeInstanceOf(CronError);
+    }
+  }
+  expect(Date.now() - start).toBeLessThan(2000);
+});

